import{j as e}from"./motion-DEWNdVTz.js";import{f as l,r as n,L as r}from"./react-vendor-Ds9ujRdZ.js";import{g as a}from"./gsap-DDlvirwQ.js";import{S as d}from"./index-DYBOR7Qt.js";import"./icons-CrZ1QwyI.js";const h={"whatsapp-to-government-portal-visa-automation":{title:"From WhatsApp Photo to Government Portal: Automating Visa Processing",date:"June 14, 2026",dateISO:"2026-06-14",description:"How UmrahFlow takes a pilgrim from a WhatsApp message to a staged Umrah visa submission — an AI agent, passport OCR, a human-review dashboard, and a bridge into the Saudi Nusuk portal that deliberately stops one step short.",tags:["AI Agents","WhatsApp","OCR","Claude","Automation"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Umrah visa processing is a paperwork business run over WhatsApp. Agents receive passport photos in chat, retype the details into spreadsheets, and then retype them ",e.jsx("i",{children:"again"})," into the Saudi Nusuk portal. Every retype is a chance for a typo that costs a pilgrim their trip. UmrahFlow, a freelance project I built, automates that pipeline end to end — from the first WhatsApp photo to a staged, ready-to-submit visa job — while deliberately keeping one human decision in the middle and one at the end."]}),e.jsx("h3",{children:"The Shape of the Pipeline"}),e.jsxs("p",{children:["The system is a chain of five services. A ",e.jsx("b",{children:"WhatsApp relay"})," receives messages from pilgrims on the agency's own number and forwards them, Twilio-webhook-shaped, to a ",e.jsx("b",{children:"Next.js dashboard"})," backed by Postgres. A background ",e.jsx("b",{children:"agent service"})," drains unprocessed messages: it classifies each one, runs any images through an ",e.jsx("b",{children:"OCR service"}),", creates passport records, and replies to the pilgrim on WhatsApp. Staff then review the extracted passports in the dashboard. When they approve one, a ",e.jsx("b",{children:"bridge service"})," picks it up, builds a submission plan, and stages it as a job in the operator's visa console — where a human runs the actual submission to the government portal."]}),e.jsx("h3",{children:"Why an Agent Loop Instead of a Webhook Handler"}),e.jsxs("p",{children:["The tempting design is to process each incoming webhook inline: message arrives, OCR runs, reply goes out. I built it as a drain loop instead — the dashboard just stores messages with ",e.jsx("code",{children:"processedAt = NULL"}),", and the agent polls for unprocessed rows every few seconds. This buys three things. Slow OCR never blocks the webhook. A crashed agent loses nothing, because unprocessed messages are simply still unprocessed. And most importantly, it lets the agent ",e.jsx("b",{children:"debounce"}),": pilgrims send passports as photo albums, and the loop waits for the album to finish arriving before treating it as one submission instead of six."]}),e.jsx("h3",{children:"OCR That Can Be Trusted with Passports"}),e.jsx("p",{children:"Passport data is exactly the kind of data you cannot afford to hallucinate. The OCR service merges two independent reads: a deterministic MRZ (machine-readable zone) parse and a Claude vision pass, with OpenAI as fallback. When both agree, confidence is high; when they disagree, that's signal for the human reviewer. The service returns fields in the exact shape the dashboard's upload code expects, so extracted passports flow straight into the review UI. (The OCR design gets its own post — it's the most interesting piece of the system.)"}),e.jsx("h3",{children:"The Human Gate in the Middle"}),e.jsxs("p",{children:["Nothing goes from OCR to the government pipeline automatically. Staff see each passport in the dashboard with its extracted fields and the original photos side by side. Only an explicit approval flips the passport's status to ",e.jsx("code",{children:"QUEUED"})," — and that status change is the entire interface between the review side and the submission side. It's a state machine, not an API call: the dashboard never talks to the bridge directly, it just changes a database field, and the bridge leases whatever is queued."]}),e.jsx("h3",{children:"The Bridge, and Stopping One Step Short"}),e.jsxs("p",{children:["The bridge service turns queued passports into staged submission jobs. Crucially, it builds each submission plan using the visa console's ",e.jsx("i",{children:"own"})," plan builder — importing the client's existing code rather than reimplementing its logic, so the staged job is exactly what the console would have produced by hand. The final step, actually submitting to Nusuk, requires the operator to log in and run the submission command deliberately. That's not a missing feature. Submitting to a government portal on someone's behalf is the one action in the pipeline that is irreversible, high-stakes, and reputationally fatal to get wrong — so it stays behind a human keystroke."]}),e.jsx("h3",{children:"Verifying the Whole Chain"}),e.jsxs("p",{children:["A pipeline like this fails at the seams, not in the middles. So the repo ships a smoke script that runs eleven end-to-end checks: every service's health endpoint, a full agent turn (message in → passport out → reply sent), and bridge staging. One command answers the only question that matters after any change: ",e.jsx("i",{children:"does a WhatsApp photo still become a staged visa job?"})]}),e.jsx("h3",{children:"Takeaways"}),e.jsxs("p",{children:["Three decisions defined UmrahFlow. Model the pipeline as ",e.jsx("b",{children:"states in a database"}),", not calls between services — it makes every step resumable and inspectable. Put ",e.jsx("b",{children:"AI where reading is hard and humans where mistakes are expensive"}),". And when your automation touches an external system of record, ",e.jsx("b",{children:"stop one step short"})," and hand the human a loaded, verified, one-keystroke action. The agency processes passports in a fraction of the time, and no pilgrim's visa ever rides on an unreviewed AI guess."]})]})},"passport-ocr-mrz-claude-vision":{title:"Reading Passports with AI: Merging MRZ Parsing with Claude Vision",date:"June 21, 2026",dateISO:"2026-06-21",description:"MRZ parsing is deterministic but brittle; vision models read anything but can hallucinate. Why UmrahFlow's passport OCR cross-checks a local MRZ pass against a Claude vision pass — and falls back to OpenAI when it must.",tags:["Claude","Computer Vision","OCR","Python","AI/ML"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"For UmrahFlow, my Umrah visa-automation platform, I needed to turn WhatsApp photos of passports into structured data — names, passport numbers, dates, nationality — reliably enough to feed a government visa submission. Neither classic OCR nor an AI vision model alone was good enough. The answer was to run both and merge them, which turned out to be the most interesting engineering problem in the whole project."}),e.jsx("h3",{children:"Why MRZ Alone Isn't Enough"}),e.jsxs("p",{children:["Every passport has an MRZ — those two lines of ",e.jsx("code",{children:"<<<"}),"-padded text at the bottom. It's designed for machines: fixed positions, restricted character set, and ",e.jsx("b",{children:"check digits"})," over the passport number, birth date, and expiry date. When an MRZ read validates, you can trust it almost completely. The problem is the input: these are phone photos taken in queues and living rooms — glare across the laminate, fingers over corners, perspective skew, compression from WhatsApp. On real-world photos, a local MRZ pass fails or garbles far too often to run a business on."]}),e.jsx("h3",{children:"Why a Vision Model Alone Isn't Either"}),e.jsxs("p",{children:["Claude's vision reads passports impressively — skewed, glared, even partially covered. It also reads the ",e.jsx("i",{children:"visual zone"}),` (the printed fields), which contains data the MRZ doesn't carry, like place of birth. But a vision model's failure mode is the dangerous one: it doesn't say "unreadable," it produces a `,e.jsx("i",{children:"plausible"})," passport number. A wrong-but-confident digit in a visa application is strictly worse than a hard failure, because nothing downstream looks broken."]}),e.jsx("h3",{children:"Two Readers, One Merge"}),e.jsxs("p",{children:["So the OCR service runs both passes and merges field by field. The rules are simple and boring on purpose. If the MRZ parses and its check digits validate, MRZ wins for the fields it covers — it's cryptographically self-verifying and can't hallucinate. Claude fills the fields MRZ doesn't have and covers the photos where MRZ failed entirely. When both read a field and they ",e.jsx("i",{children:"disagree"}),", that disagreement is preserved as a low-confidence flag instead of silently picking one — because downstream, a human reviewer sees the extracted fields next to the original photo, and their attention should go exactly where the readers diverged."]}),e.jsx("h3",{children:"The Fallback Chain"}),e.jsx("p",{children:"The vision pass itself has a fallback: Claude first, OpenAI if Claude errors or times out. Provider redundancy matters more in this system than in most, because the input arrives in bursts (a group's ten passports at once, right before a deadline) and the whole agency's intake stalls if extraction is down. The two providers sit behind one internal interface, so the merge logic neither knows nor cares which model did the reading."}),e.jsx("h3",{children:"The Contract: snake_case Under ‘primary’"}),e.jsxs("p",{children:["One unglamorous detail did a lot of work: the service returns fields in the ",e.jsx("i",{children:"exact"})," shape the existing dashboard's upload code digs into — snake_case fields nested under a ",e.jsx("code",{children:"primary"})," key. The dashboard predates my services and I'd committed to not changing its code, so the OCR API was built to its consumer's expectations rather than my aesthetic preferences. Endpoints stayed minimal: ",e.jsx("code",{children:"POST /ocr"})," for multipart uploads, ",e.jsx("code",{children:"POST /ocr/url"})," for images already stored, ",e.jsx("code",{children:"POST /pdf"})," for scanned documents, and ",e.jsx("code",{children:"GET /healthz"})," for the smoke test."]}),e.jsx("h3",{children:"What I'd Tell You to Steal"}),e.jsxs("p",{children:['The pattern generalizes to any "AI reads a document" problem: pair a ',e.jsx("b",{children:"deterministic validator"})," (check digits, checksums, regex with known structure) with a ",e.jsx("b",{children:"flexible reader"})," (vision model), let the validator win where it can, and surface disagreement to a human instead of resolving it silently. You get the vision model's coverage without inheriting its confidence problem. AI does the reading; arithmetic does the trusting."]})]})},"building-microservices-to-someone-elses-contract":{title:"Building Microservices to Someone Else's Contract",date:"June 28, 2026",dateISO:"2026-06-28",description:"The dashboard already existed; its ML services didn't. How I rebuilt two missing services to the exact API shape an existing app expected — without changing a line of dashboard code — and made five services start with one command.",tags:["Microservices","FastAPI","Docker","API Design","DevOps"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Most microservices posts start from a blank slate: design the services, then the contracts, then build. UmrahFlow, a freelance visa-automation project, handed me the opposite problem. The client had three working repos — a Next.js review dashboard, a visa-submission console, and a WhatsApp relay — that referenced an ML services repo that ",e.jsx("b",{children:"didn't exist anymore"}),". The dashboard was full of calls to an OCR service and assumptions about a background agent, with no implementation behind them. My job: rebuild the missing services so everything works, without touching the client's code."]}),e.jsx("h3",{children:"The Contract Was Already Written — In the Consumer"}),e.jsxs("p",{children:["With no spec and no old code, the API contract had to be excavated from the caller. The dashboard's upload logic told me the OCR response shape (snake_case fields nested under ",e.jsx("code",{children:"primary"}),"); its Prisma schema told me what the agent had to produce (",e.jsx("code",{children:"Passport"})," rows, ",e.jsx("code",{children:"AgentTrace"})," rows, messages flipped from ",e.jsx("code",{children:"processedAt = NULL"}),"); its env vars told me the expected ports. Consumer-driven contracts are usually described as a testing discipline — here they were literally the only spec. The rule I set myself: ",e.jsx("b",{children:"if the dashboard needs a change, my service is wrong."})," That constraint sounds limiting, but it's actually clarifying — every design question has an objective answer, found in someone else's code."]}),e.jsx("h3",{children:"Two Services, Two Shapes"}),e.jsxs("p",{children:["The rebuilt ",e.jsx("b",{children:"OCR service"})," is a classic request/response API in Python: multipart image in, structured passport fields out, with the MRZ + Claude vision merge described in my previous post. The ",e.jsx("b",{children:"agent service"})," is barely an API at all — one ",e.jsx("code",{children:"/healthz"})," route and a background drain loop that polls for unprocessed messages, runs OCR, writes records, and replies over WhatsApp. I resisted the urge to give the agent a REST surface. Its consumers are database rows, not HTTP callers; a poll loop against Postgres is simpler, crash-safe, and needs no retry logic on the sending side."]}),e.jsx("h3",{children:"The Bridge: Borrowing the Client's Own Logic"}),e.jsxs("p",{children:["The third piece, the bridge, moves approved passports into the visa console as staged submission jobs. The console has intricate logic for building a valid submission plan — and the worst thing I could do is reimplement it and let two versions drift. So the bridge runs inside the console's own Python environment and imports its plan builder directly. The bridge stays a thin state-machine pump: lease ",e.jsx("code",{children:"QUEUED"})," passports, call ",e.jsx("i",{children:"their"})," builder, stage the job. When the client updates their console, the bridge inherits the changes for free."]}),e.jsx("h3",{children:"One Command or It Doesn't Count"}),e.jsxs("p",{children:["Five services across two languages, two of them the client's, plus Postgres and a WhatsApp container — that's a fragile dev environment unless you make orchestration a feature. A Makefile became the single control surface: ",e.jsx("code",{children:"make up"})," starts everything (Docker Compose for infra, native processes for the apps), ",e.jsx("code",{children:"make health"})," hits every health endpoint, ",e.jsx("code",{children:"make down"})," stops it all. One shared env file feeds every service, so a credential exists in exactly one place. None of this is glamorous, but it's the difference between a system a client can run and a diagram they can admire."]}),e.jsx("h3",{children:"Smoke Tests Over Unit Tests"}),e.jsx("p",{children:"With this architecture the risk isn't inside any one service — it's the seams. So the primary verification is an 11-check smoke script: every health endpoint, then a real agent turn (inject a message, watch a passport appear, see the reply go out), then bridge staging. It runs after every meaningful change and answers the integration question directly instead of by inference from mocks."}),e.jsx("h3",{children:"Takeaways"}),e.jsx("p",{children:"Building to someone else's contract inverts the usual instincts: read the consumer before designing the producer; match its conventions even where you'd choose differently; import their logic instead of reimplementing it; and spend your testing budget on the seams. The reward is a drop-in replacement — the client's dashboard worked without a single edit, which was the whole assignment."})]})},"taming-whatsapp-as-an-app-input":{title:"Taming WhatsApp as an App Input: Debouncing Albums, Draining Queues",date:"July 05, 2026",dateISO:"2026-07-05",description:"WhatsApp is a terrible API and a perfect UX. How UmrahFlow turns messy real-world messages — photo albums, doubles, mixed chatter — into clean records with a Twilio-compatible relay, debounced draining, and agent traces.",tags:["WhatsApp","WAHA","Message Queues","Integrations","Python"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"If your users are Umrah pilgrims, the interface question answers itself: they are already on WhatsApp, and they will not install your app. So UmrahFlow's entire intake runs through WhatsApp — which means turning the messiest input stream imaginable into clean database records. Photos arrive as albums, messages arrive twice, questions arrive mixed in with documents. Here's the machinery that copes."}),e.jsx("h3",{children:"Own Number via WAHA, Twilio-Shaped Wire"}),e.jsxs("p",{children:["The first choice was infrastructure. The official WhatsApp Business API means Meta approval flows and per-conversation pricing; for an agency that lives on its ",e.jsx("i",{children:"existing"})," WhatsApp number, WAHA (WhatsApp HTTP API) is the pragmatic self-hosted route — it runs in a container and speaks plain HTTP. In front of it sits a small relay that exposes a ",e.jsx("b",{children:"Twilio-compatible"})," webhook format. That deliberate translation layer means the dashboard just implements a standard Twilio webhook — and if the business ever migrates to the official API via Twilio, the dashboard doesn't change at all. The relay is an adapter, and adapters are cheapest when they imitate a format the ecosystem already understands."]}),e.jsx("h3",{children:"Store First, Process Later"}),e.jsxs("p",{children:["The webhook handler does almost nothing: it writes the message to Postgres and returns 200. All real work happens in a separate agent service that polls for messages with ",e.jsx("code",{children:"processedAt = NULL"})," on bot-enabled conversations. This store-first pattern is what makes WhatsApp's chaos manageable — webhooks never time out no matter how slow OCR is, a crashed agent resumes exactly where it left off because unprocessed rows are still unprocessed, and retried webhook deliveries can be deduplicated at write time instead of causing double replies."]}),e.jsx("h3",{children:"The Album Problem"}),e.jsxs("p",{children:["The subtle bug in any naive implementation: a pilgrim selects six passport photos and hits send. WhatsApp delivers six separate messages over several seconds. Process each on arrival and you run OCR six times, create six passport batches, and send six replies — the bot looks broken to exactly the person you're trying to impress. The fix is a ",e.jsx("b",{children:"debounce window"}),`: the drain loop only picks up a conversation once no new message has arrived for a quiet period. Photos that arrive together are processed together, one batch, one reply. It's a few lines of SQL filtering by timestamp, and it's the difference between "wow" and "what is this thing doing."`]}),e.jsx("h3",{children:"Not Everything Is a Passport"}),e.jsxs("p",{children:["Real conversations interleave documents with chatter — greetings, questions, voucher photos, the occasional selfie. Before anything touches OCR, a classification step routes each drained batch: passport images go to extraction, voucher images to voucher handling, text gets a conversational reply. Classification errors are cheap ",e.jsx("i",{children:"because"})," of the human-review stage downstream — a selfie classified as a passport produces a garbage extraction a reviewer deletes in two seconds, not a corrupted visa application."]}),e.jsx("h3",{children:"Traces, Because Chat Is Invisible"}),e.jsxs("p",{children:["A web app shows you what the user saw; a chat pipeline doesn't. So every agent turn writes an ",e.jsx("code",{children:"AgentTrace"}),` — what was drained, how it was classified, what OCR returned, what reply was sent. When an agency staffer asks "why did the bot say this," the answer is a database query, not archaeology. If you build any conversational automation, build the trace table on day one; you cannot debug what you didn't record.`]}),e.jsx("h3",{children:"Takeaways"}),e.jsxs("p",{children:["WhatsApp gives you users with zero onboarding and repays you with an input stream full of edge cases. The taming pattern: ",e.jsx("b",{children:"adapt to a standard wire format"})," at the edge, ",e.jsx("b",{children:"store before processing"}),", ",e.jsx("b",{children:"debounce bursts into batches"}),", ",e.jsx("b",{children:"classify before acting"}),", and ",e.jsx("b",{children:"trace everything"}),". Get those five right and the messiest channel in software becomes a reliable front door."]})]})},"modeling-real-store-tickets-and-bills-pos":{title:"Modeling a Real Cloth House: Why My POS Has Tickets AND Bills",date:"July 12, 2026",dateISO:"2026-07-12",description:"In a multi-department Pakistani cloth store, where a sale is recorded and where money is taken are different places. How that one domain insight shaped a Prisma schema of tickets, bills, shifts, and escalations.",tags:["Prisma","PostgreSQL","Data Modeling","Next.js","Retail Tech"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["I'm building a POS as a freelance project for Sher-e-Punjab Cloth House — a multi-department clothing store in Attock with a branch in Kamra. Before writing any code, I spent time understanding how the shop actually moves money. That produced the one domain insight the entire schema hangs on: ",e.jsx("b",{children:"where a sale is recorded and where money is taken are different places."})," Miss that, and no amount of clean code makes the system match reality."]}),e.jsx("h3",{children:"How a Multi-Department Store Actually Works"}),e.jsx("p",{children:"A customer browses the fabric floor, picks something, and the department staff ring it up — but no money changes hands there. The customer gets a numbered slip and keeps shopping: another slip from menswear, another from the children's floor. At the exit sits one central counter where all slips are combined and paid in a single transaction. Departments sell; the counter collects. Every off-the-shelf POS I looked at assumes these are the same event. They aren't."}),e.jsx("h3",{children:"Tickets and Bills as First-Class Entities"}),e.jsxs("p",{children:["So the schema has two distinct aggregates. A ",e.jsx("code",{children:"Ticket"})," is a department's record of a sale: its line items, its department, the staffer who rang it, a human-legible sequential number, and a status. A ",e.jsx("code",{children:"Bill"})," is the counter's record of a payment, joined to one or more tickets, with the payment method and the checkout staffer. The join table between them isn't plumbing — it ",e.jsx("i",{children:"is"}),' the business event of "these three slips were settled together." Returns and exchanges then hang off this structure with their own models, because "customer returns the menswear item from a three-ticket bill" has to be expressible precisely: which line item, which decision, which refund method, settled how.']}),e.jsx("h3",{children:"Stock Lives Per Department"}),e.jsxs("p",{children:["Inventory follows the same logic. Products and variants are catalog-level, but stock is a ",e.jsx("code",{children:"DepartmentStock"})," row — the same shirt can be plentiful upstairs and sold out at the branch. That per-department granularity is what makes the owner's stock view honest, and it localizes discrepancies: when a count is off, you know ",e.jsx("i",{children:"which floor"})," to ask."]}),e.jsx("h3",{children:"Shifts Make Cash Auditable"}),e.jsxs("p",{children:["Cash is the other half of trust. A ",e.jsx("code",{children:"Shift"})," records a drawer session: who opened it, with how much float, and the counted total at close. Because every bill is stamped with its staffer and till, expected-versus-counted is a query, not an argument. The schema's job here is social as much as technical — staff are protected by the record, and the owner sees discrepancies as data instead of suspicion."]}),e.jsx("h3",{children:"Escalations: Authority in the Schema"}),e.jsxs("p",{children:["In a family-run store, some actions are the owner's alone — big discounts, voiding a ticket, an unusual refund. Rather than burying that in UI logic, there's an ",e.jsx("code",{children:"EscalationRequest"})," model: a till raises a typed request, the owner approves or rejects it, and the decision is permanently linked to the ticket it affected. Combined with an append-only ",e.jsx("code",{children:"AuditLog"})," on sensitive actions, the rule is simple: ",e.jsx("b",{children:"if it involves money or authority, it leaves a row."})]}),e.jsx("h3",{children:"Why Prisma 7 + Postgres"}),e.jsxs("p",{children:["This domain is relational to its bones — tickets joining bills, stock per department, decisions linked to documents. Postgres gives real foreign keys and transactions (a bill and its ticket-status flips commit atomically or not at all), and Prisma 7 with the ",e.jsx("code",{children:"pg"})," driver adapter gives a typed schema that doubles as living documentation of the domain model. A document store would have forced me to hand-roll exactly the integrity the business depends on."]}),e.jsx("h3",{children:"Takeaways"}),e.jsxs("p",{children:["The generalizable lesson: ",e.jsx("b",{children:"find the place where the real-world process splits what software habitually merges."})," Here it was sale-versus-payment; the tickets/bills split unlocked the rest of the model — returns, shifts, escalations — almost mechanically. Schema design was mostly anthropology, and the code is better for it."]})]})},"designing-ui-for-repetitive-retail-work":{title:"Designing UI for People Who Do the Same 5 Actions 300 Times a Day",date:"July 19, 2026",dateISO:"2026-07-19",description:'Retail staff are not "users exploring an interface" — they are operators under time pressure. How I designed a POS around tabular numerals, state-only color, keyboard-first tills, and chrome that disappears into the sale.',tags:["UI/UX","Tailwind CSS","Accessibility","Design Systems","POS"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Most interface advice assumes a user who is discovering your product. The staff at a cloth-house till are the opposite: they perform the same five actions — search, add, adjust, total, hand over the slip — hundreds of times a day, on their feet, under bright shop lighting, while a customer waits. Designing the POS for Sher-e-Punjab Cloth House meant designing for ",e.jsx("i",{children:"operators"}),", and almost every conventional instinct had to be inverted."]}),e.jsx("h3",{children:"The Till Disappears Into the Sale"}),e.jsxs("p",{children:["The first principle: chrome never competes with the cart. Every frequent action is one glance and one tap, the current ticket dominates the screen, and nothing decorative sits near the transaction. Onboarding hints, illustrations, empty-state mascots — all the things that help a first-time user — are pure friction for someone on rep three hundred. For operators, the kindest interface is the one that gets out of the way; speed ",e.jsx("i",{children:"is"})," the UX."]}),e.jsx("h3",{children:"Numbers Are Typography"}),e.jsx("p",{children:"A POS screen is mostly numbers: prices, quantities, stock counts, ticket numbers, drawer totals. So numbers get typographic respect — always tabular/monospaced figures, so digits align in columns and a price doesn't jiggle as it updates; sized to be read at arm's length; never truncated. Proportional figures are for prose. When checkout staff are comparing a counted drawer against an expected total, aligned digits are the difference between an instant visual diff and a squint."}),e.jsx("h3",{children:"Color's Only Job Is State"}),e.jsxs("p",{children:["The palette is a contract, not a decoration scheme: emerald means action, gold means identity and selection, amber means warning, red means danger or stock-out. Nothing else is colored. The payoff is Pavlovian — when color ",e.jsx("i",{children:"only"}),` ever means state, peripheral vision does the monitoring, and a flash of amber registers before the staffer has consciously read anything. Every gradient background and colorful illustration you add taxes exactly that channel. (The store's brand — "Lion of Punjab," steel with one thread of gold — actually made restraint easier to sell than flash.)`]}),e.jsx("h3",{children:"Keyboard-First, Because Scanners Are Keyboards"}),e.jsx("p",{children:'Barcode scanners present as keyboards, and till staff live on physical keys. So every till flow is fully operable without a mouse: scan, arrows, enter, done. Visible gold focus rings show exactly where input goes — under WCAG AA contrast in both themes, which matters doubly here because "keyboard accessible" and "fast for power users" turn out to be the same feature. Accessibility work usually pitched as compliance is, at a till, straightforwardly throughput.'}),e.jsx("h3",{children:"One Vocabulary Across Three Surfaces"}),e.jsxs("p",{children:["The POS has three very different surfaces — department till, central checkout, owner dashboard — but one component vocabulary: the same button system, field system, and header system, built on Tailwind v4 design tokens. Staff rotate between floors and counters, and consistency means their muscle memory transfers. The tokens also enforce the color contract and AA contrast at the system level, so a rushed feature ",e.jsx("i",{children:"can't"})," quietly introduce an off-palette blue or an illegible gray."]}),e.jsx("h3",{children:"Motion Only Conveys State"}),e.jsxs("p",{children:["Animation is capped at 150–250ms and only ever communicates a state change — a ticket confirmed, a row added. ",e.jsx("code",{children:"prefers-reduced-motion"})," is respected everywhere. Delightful motion is lovely in a consumer app; at rep three hundred, a 400ms flourish is a tax someone pays all day. Light and dark themes ship with a persistent per-station toggle, because a till by the window and a back office at night are different lighting realities."]}),e.jsx("h3",{children:"Takeaways"}),e.jsx("p",{children:`Designing for operators means optimizing the thousandth use, not the first: strip chrome, respect numbers typographically, reserve color for state, treat the keyboard as the primary device, and keep one vocabulary everywhere. "Boring, fast, and legible" is not a compromise aesthetic — for this kind of software it's the whole point, and it photographs worse than it feels.`})]})},"multi-tenant-from-day-one-pos-saas":{title:"Multi-Tenant from Day One: Building for One Store, Architecting for SaaS",date:"July 26, 2026",dateISO:"2026-07-26",description:"My POS has exactly one customer, but every table has a tenantId. What multi-tenancy actually cost to add up front, what it buys later, and where the line is between preparing for SaaS and over-engineering.",tags:["SaaS","Multi-Tenancy","Next.js","Architecture","Prisma"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["The POS I'm building has exactly one customer: a cloth house in Attock with a branch in Kamra. And yet the very first model in the Prisma schema is ",e.jsx("code",{children:"Tenant"}),`, and nearly every table hangs off it. "You aren't gonna need it" is usually right, and premature SaaS architecture is a classic way to kill a simple project — so this post is my honest accounting of why I broke the rule, what it actually cost, and where I drew the line.`]}),e.jsx("h3",{children:"The Asymmetry That Justifies It"}),e.jsxs("p",{children:['Multi-tenancy is nearly unique among "later" features in how brutally its cost curve bends. Adding ',e.jsx("code",{children:"tenantId"})," to a fresh schema is hours of work. Retrofitting it into a live system means migrating every table, rewriting every query, re-testing every report, and auditing every endpoint for cross-tenant leaks — all against production data whose integrity is the product. Most speculative features cost about the same whenever you build them; tenancy costs 100× more later. That asymmetry, plus a client who explicitly sees this as a product for other stores eventually, made day-one tenancy the cheap option."]}),e.jsx("h3",{children:"What It Actually Looks Like"}),e.jsxs("p",{children:["The implementation is deliberately unclever: a shared database where ",e.jsx("code",{children:"Tenant"}),' sits at the root and departments, users, products, tickets, bills, shifts, and audit logs all carry the scoping. Uniqueness is tenant-scoped (two stores can both have a "Menswear" department; ticket numbering is per-tenant), and every query runs through a data layer that takes tenant context from the authenticated session — never from client input. No separate databases per tenant, no dynamic schemas. For a system whose tenants are cloth stores rather than banks, row-level scoping in one Postgres database is the right amount of isolation.']}),e.jsx("h3",{children:"The Surprise: Tenancy Improved the Single-Store Design"}),e.jsxs("p",{children:[`The unexpected benefit was rigor. Deciding, for every table, "does this belong to the tenant, a department, or a user?" forced ownership questions I'd otherwise have answered lazily — and it caught real modeling errors early. Is the product catalog tenant-wide with per-department stock, or per-department entirely? Working through it produced the `,e.jsx("code",{children:"CatalogScope"})," concept and the clean catalog/stock split that the whole inventory feature now rests on. The discipline of tenancy is mostly the discipline of knowing who owns what, and that pays off even with one tenant."]}),e.jsx("h3",{children:"Where I Drew the Line"}),e.jsxs("p",{children:["Everything that would make multi-tenancy ",e.jsx("i",{children:"operational"})," — self-serve signup, tenant provisioning flows, billing and subscriptions, per-tenant theming, a super-admin console — does not exist. That's the over-engineering trap: those features are exactly the ones that are ",e.jsx("i",{children:"cheap to add later"})," (they're additive, not structural) and expensive to maintain now. The rule I'd generalize: ",e.jsx("b",{children:"bake in what's structural, defer what's additive."})," Schema scoping is structural. A pricing page is additive."]}),e.jsx("h3",{children:"Auth Follows the Same Pattern"}),e.jsx("p",{children:`Supabase handles authentication, and role-based access (department staff, checkout staff, owner) is enforced in the data layer alongside tenant scoping — the session resolves to a user, the user to a role and a tenant, and every query inherits both. Getting authorization and tenancy into the same chokepoint means there's one place where "who can see what" lives, which is precisely the code you want boring and centralized when tenant two arrives.`}),e.jsx("h3",{children:"Takeaways"}),e.jsx("p",{children:"Multi-tenancy from day one isn't a universal rule — it's a bet on cost asymmetry. Take it when retrofit cost is catastrophic, a plausible product path exists, and you can resist building the operational layer prematurely. Skip it when SaaS is a fantasy. For this POS the bet has already paid for itself once — in schema rigor — before a second tenant ever shows up."})]})},"when-not-to-let-ai-finish-the-job":{title:"When NOT to Let the AI Finish the Job",date:"August 02, 2026",dateISO:"2026-08-02",description:"Two production systems, one lesson: the most valuable line of code in an automation platform is the one that stops and asks a human. Why UmrahFlow halts before the government portal and why my POS makes owners approve discounts.",tags:["AI Agents","Human-in-the-Loop","Automation","Trust","Opinion"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["This year I shipped two automation-heavy freelance systems back to back: UmrahFlow, which turns WhatsApp passport photos into staged government visa submissions, and a multi-department retail POS with owner-approval escalations. On paper they automate very different things. In practice they converged on the same design move — and it's the move I now think defines whether an automation system survives contact with the real world: ",e.jsx("b",{children:"the deliberate stop."})]}),e.jsx("h3",{children:"Two Systems, Same Shape"}),e.jsxs("p",{children:["UmrahFlow automates aggressively — an AI agent classifies WhatsApp messages, OCR reads passports with Claude vision cross-checked against MRZ check digits, a bridge builds complete submission plans. Then it stops. The final submission to the Saudi Nusuk portal requires an operator to log in and run it by hand. The POS automates ticketing, billing, stock, and reconciliation — but a big discount, a voided ticket, or an unusual refund becomes an ",e.jsx("code",{children:"EscalationRequest"})," that waits for the owner. Neither stop is a missing feature or an AI limitation. In both systems the automation could trivially take the last step. It is ",e.jsx("i",{children:"forbidden"})," from taking it."]}),e.jsx("h3",{children:"Where to Put the Stop"}),e.jsxs("p",{children:["The pattern behind both decisions: automate everything ",e.jsx("b",{children:"reversible"}),", gate everything ",e.jsx("b",{children:"irreversible"}),". A misclassified WhatsApp message costs a reviewer two seconds; a wrong submission to a government portal can cost a pilgrim their pilgrimage and an agency its standing. A mis-rung ticket can be voided; a granted discount is money already out the door. So the gate goes exactly at the reversibility boundary — not at the start of the pipeline, where it would strangle the automation's value, and not after the end, where it would merely observe damage. Cost of a wrong action, divided by cost of asking, tells you where the human belongs."]}),e.jsx("h3",{children:"A Good Stop Is a Loaded Action"}),e.jsx("p",{children:`Human-in-the-loop fails when it means "human does the work anyway." The craft is in what the human receives. UmrahFlow's operator doesn't retype passport data — they get a fully staged, validated submission job and contribute one deliberate keystroke. The POS owner doesn't reconstruct a sale — they get a typed request linked to the exact ticket and amount, answerable from a phone in seconds. The automation does 99% of the work; the human supplies the 1% that is pure judgment and accountability. If your approval step takes longer than the task it approves, you haven't designed a gate — you've designed a bottleneck with extra steps.`}),e.jsx("h3",{children:"The Stop Is Why You Get to Automate the Rest"}),e.jsxs("p",{children:["Here's the commercially interesting part: the human gate is what makes the aggressive automation ",e.jsx("i",{children:"acceptable"}),". The visa agency tolerates an AI agent answering their customers on WhatsApp precisely because nothing reaches the government without staff approval. The store owner tolerates staff-run tills precisely because authority-requiring actions escalate to them. Trust in the whole system is anchored by the checkpoint. Remove it and every upstream automation becomes a liability negotiation; keep it and the automation upstream can be fearless."]}),e.jsx("h3",{children:"Accountability Is Load-Bearing"}),e.jsx("p",{children:`There's also a blunter reason: an AI cannot be accountable to the Saudi government, and a till cannot be accountable for the owner's margins. When something goes wrong, "the model decided" is not an answer any regulator, client, or family business accepts. The deliberate stop keeps a human being attached to the consequences — and both of my systems write that attachment down, in agent traces and audit logs, so the chain of judgment is reconstructable years later.`}),e.jsx("h3",{children:"Takeaways"}),e.jsx("p",{children:"As models get better, the temptation is to move the line and let the AI finish the job. My experience shipping these two systems points the other way: the better the automation, the more valuable the well-placed stop, because more rides on each remaining human decision. Automate the reversible. Gate the irreversible. Hand the human a loaded, one-keystroke action with full context. The most valuable line of code I wrote this year checks a status field and waits."})]})},"building-a-9-agent-ai-backend-for-bpoai":{title:"How the BPOAI Agent Flow Works",date:"June 18, 2026",dateISO:"2026-06-18",description:"How I built the agent server behind BPOAI — nine specialized Claude-powered agents that scrape leads, score AI readiness, verify claims, run email outreach drips, and publish weekly news, all wired together through webhooks and cron.",tags:["AI Agents","Claude","Apify","Supabase","Express"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["BPOAI is a directory and intelligence hub for the BPO industry that I led at AIDEVGEN. The public Next.js site is only half the story — behind it runs a completely separate ",e.jsx("b",{children:"agent server"}),": a small Express app whose entire job is to make the directory feel alive. It scrapes new companies, scores them, verifies ownership claims, runs cold-email campaigns, and writes weekly news, with almost no human in the loop. This post is a walkthrough of how those nine agents are wired together."]}),e.jsx("h3",{children:"Two Apps, One Webhook Contract"}),e.jsxs("p",{children:["The main site and the agents are deliberately kept apart. The Next.js app never runs an agent inline; it just fires a webhook. A tiny helper POSTs to ",e.jsx("code",{children:"${AGENT_SERVER}/webhook/{event}"})," with an ",e.jsx("code",{children:"x-agent-secret"})," header and — crucially — swallows every error so an agent outage can ",e.jsx("i",{children:"never"})," break the main site. The agent server is an Express app exposing routes like ",e.jsx("code",{children:"/webhook/search"}),", ",e.jsx("code",{children:"/webhook/claim-submit"}),", ",e.jsx("code",{children:"/webhook/profile-update"}),", and a few ",e.jsx("code",{children:"/webhook/cron/*"})," endpoints. That clean contract is what lets the agents evolve, crash, and redeploy independently of the customer-facing site."]}),e.jsx("h3",{children:"The Search → Scrape → Outreach Chain"}),e.jsxs("p",{children:["The most interesting flow starts with a failed search. ",e.jsx("b",{children:"Agent 1 (Search)"})," logs every directory query to Supabase and Slack. If a search returns zero results, it sets a flag that fires ",e.jsx("b",{children:"Agent 2 (Scraper)"})," in the background — the response to the site returns immediately, the scrape runs after."]}),e.jsxs("p",{children:["Agent 2 is the workhorse. It uses Apify's ",e.jsx("code",{children:"compass/crawler-google-places"})," actor to find matching BPO companies on Google Maps, then ",e.jsx("code",{children:"apify/website-content-crawler"})," to pull text from each company's site, and a regex-based extractor to harvest contact emails (preferring role inboxes like ",e.jsx("code",{children:"info@"})," and ",e.jsx("code",{children:"sales@"})," on the matching domain). New leads are de-duplicated and written to Supabase. Then it ",e.jsx("i",{children:"chains two more agents"}),": ",e.jsx("b",{children:"Agent 8"})," to notify anyone who requested that scan, and ",e.jsx("b",{children:"Agent 9"})," to kick off an outreach campaign for every lead that has an email."]}),e.jsx("h3",{children:"Outreach as a Drip, Stopped by Replies"}),e.jsxs("p",{children:[e.jsx("b",{children:"Agent 9 (Outreach)"})," is a three-email drip. The first email goes out the moment a lead is created; an hourly cron (",e.jsx("code",{children:"/webhook/cron/outreach"}),") sends follow-up #2 at +24h and #3 at +48h. A unique DB index prevents the same lead being enrolled twice, and an admin master switch can pause all outreach at once. The clever part is the feedback loop: when a recipient replies, Resend's ",e.jsx("code",{children:"email.received"})," webhook hits the server, ",e.jsx("b",{children:"Agent 8"})," stores the reply, and it calls back into Agent 9 to mark the campaign ",e.jsx("i",{children:"replied"}),` and stop the drip. No one wants a "just following up" email after they've already answered.`]}),e.jsx("h3",{children:"Scoring and Claims: AI Where It Earns Its Keep"}),e.jsxs("p",{children:["Two agents lean directly on Claude. ",e.jsx("b",{children:"Agent 3 (Scoring)"})," fires on every profile update and asks Claude to compute an ",e.jsx("b",{children:"AI Readiness Score"}),` (0–100) from the company's listed tools, services, and profile completeness — auto-awarding an "AI-Ready" badge at 70+. `,e.jsx("b",{children:"Agent 5 (Claims)"})," handles ownership claims by comparing the claimant's email domain to the company's website domain: a match auto-approves and emails the user; a mismatch is queued to an admin Slack channel for manual review. Claude is used where judgment helps; a plain domain check is used where it's all you need."]}),e.jsx("h3",{children:"The Weekly Cron: News and Analytics"}),e.jsxs("p",{children:["Every Monday morning, two agents wake up. ",e.jsx("b",{children:"Agent 6 (News)"})," scrapes BPO/AI headlines across a set of topics (Apify's Google-search scraper + content crawler), runs each article through Claude to produce an SEO title, summary, and clean HTML body, and saves them as ",e.jsx("i",{children:"pending drafts"}),` for an admin to approve. It also writes one original "trending" article naming the week's top-scoring and newly-added companies. `,e.jsx("b",{children:"Agent 7 (Analytics)"})," compiles weekly stats — new companies, claims, top searches, highest scores — and posts a digest to Slack. No content auto-publishes; humans stay in the approval loop where reputation is on the line."]}),e.jsx("h3",{children:"The Shared Toolbelt"}),e.jsxs("p",{children:["Four small libraries keep the agents thin. ",e.jsx("code",{children:"claude.ts"})," wraps the Claude integration and exposes typed helpers (",e.jsx("code",{children:"calculateAIScore"}),", ",e.jsx("code",{children:"generateArticleSummary"}),", ",e.jsx("code",{children:"extractBPOData"}),"). ",e.jsx("code",{children:"apify.ts"})," wraps the Google Maps and content-crawler actors. ",e.jsx("code",{children:"slack.ts"})," gives every agent a consistent way to post execution logs, lead cards, and error alerts to dedicated channels. ",e.jsx("code",{children:"emailExtract.ts"})," does the unglamorous but vital work of finding a real, reachable email on a company website. Each agent reads almost like a recipe because the messy parts live here."]}),e.jsx("h3",{children:"What Made It Reliable"}),e.jsxs("p",{children:["Three decisions did the heavy lifting. First, ",e.jsx("b",{children:"fire-and-forget by default"}),": webhooks respond instantly and the real work runs in background tasks with ",e.jsx("code",{children:".catch()"})," guards, so a slow scrape never times out a user request. Second, ",e.jsx("b",{children:"one driver per job"})," — outreach follow-ups are driven only by the external cron, never a second in-process timer, to avoid double-sending. Third, ",e.jsx("b",{children:"humans gate anything public"}),": scraped leads, AI-written articles, and ambiguous claims all wait for approval. The result is a backend that does a remarkable amount on its own while staying safe to leave running."]}),e.jsx("p",{children:"Nine agents, one webhook contract, and a handful of shared tools turn a static directory into something that grows, scores, and follows up by itself. That's the part of BPOAI users never see — and the part I had the most fun building."})]})},"designing-houses-in-the-browser-react-three-konva":{title:"Designing a Real House in the Browser: 2D Plans to Live 3D",date:"June 14, 2026",dateISO:"2026-06-14",description:"How I built homeStructure — a climate-smart house design studio for a real irregular plot in Attock, with an editable 2D floor planner (react-konva), live 3D (react-three-fiber), and a passive-design score.",tags:["Three.js","react-konva","Next.js","Zustand","3D Web"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Most house-design tools assume a clean rectangular lot. Real plots aren't like that. homeStructure is a personal project I built to design a climate-smart house on a ",e.jsx("b",{children:"real, irregular trapezoid plot"})," in Attock, Pakistan — about 2,455 sq ft (≈ 9 Marla), traced from satellite imagery, with three of four sides as shared party walls. You draw the floor plan on the exact boundary, watch it build in live 3D, and get passive-design advice tuned to a hot, semi-arid climate."]}),e.jsx("h3",{children:"One Document as the Source of Truth"}),e.jsxs("p",{children:["The whole app is driven by a single ",e.jsx("code",{children:"FloorPlan"}),' document, validated with a Zod schema and measured entirely in feet. That one document feeds the 2D editor, the 3D viewer, the model thumbnails, and the climate score. Keeping a single source of truth is what makes "edit in 2D, see it in 3D instantly" actually work without the two views drifting apart.']}),e.jsx("h3",{children:"The 2D Floor Planner (react-konva)"}),e.jsxs("p",{children:["The editor is built on react-konva. You add, drag, resize, and label rooms directly on the irregular boundary, with grid snapping and a live readout of area, Marla, and plot coverage. The hard part is constraint: rooms must stay inside a non-rectangular polygon and respect locked party walls. I used ",e.jsx("code",{children:"@flatten-js/core"})," for polygon containment and ",e.jsx("code",{children:"earcut"})," to triangulate the footprint for area calculations."]}),e.jsx("h3",{children:"Live 3D (react-three-fiber)"}),e.jsxs("p",{children:["The same plan extrudes into 3D the moment you change it, using react-three-fiber over Three.js with helpers from ",e.jsx("code",{children:"@react-three/drei"}),". There are three render modes — Massing, Realistic, and Blocks — and camera presets for Front, Back, Left, Right, Top, and Iso. Because the geometry is derived from the FloorPlan document, the 3D view is never out of sync with the 2D editor."]}),e.jsx("h3",{children:"Undo/Redo and Persistence"}),e.jsxs("p",{children:["State lives in a Zustand store, with ",e.jsx("code",{children:"zundo"})," layered on top for time-travel undo/redo — essential for a design tool where you experiment constantly. Everything autosaves to localStorage, and you can Import/Export the plan as JSON, so a design is portable and shareable as a plain data file."]}),e.jsx("h3",{children:"Climate-Smart by Design"}),e.jsx("p",{children:'Because three sides are blind party walls, every viable layout relies on a central courtyard (sehan) for light and cross-ventilation. homeStructure makes that trade-off visible: a live passive-design score plus a checklist and sun diagram covering courtyard placement, shading, roof strategy, zoning, and monsoon handling. The goal is to turn vague "good design" intuition into a concrete number you can push up as you edit.'}),e.jsx("h3",{children:"What I Learned"}),e.jsx("p",{children:"Two lessons stood out. First, deriving 3D from a single validated document is far more robust than syncing two separate models — let one representation be the truth and compute the rest. Second, constraining an editor to an irregular boundary is mostly a geometry problem; investing early in a solid containment-and-snapping layer paid off across every feature built on top of it."}),e.jsx("p",{children:"homeStructure is live and runs entirely in the browser — no installs, no plugins. It's a small proof that climate-smart planning for a real, awkward plot can be approachable, visual, and immediate."})]})},"building-a-bpo-directory-ai-hub-supabase-three":{title:"Building a BPO Directory & AI Hub with Supabase and Three.js",date:"June 02, 2026",dateISO:"2026-06-02",description:"A look at BPOAI — a directory and intelligence hub for the top BPO companies in the Philippines, combining a Supabase data layer with an immersive 3D landing experience.",tags:["Next.js","Supabase","Three.js","Framer Motion","Directory"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"The Business Process Outsourcing market in the Philippines is huge, but discovering the right provider is still a mess of outdated lists and SEO spam. BPOAI, which I led at AIDEVGEN, is a directory and intelligence hub that pairs real company data with a landing experience that doesn't feel like a phone book. Here's how it's put together."}),e.jsx("h3",{children:"Supabase as the Data Layer"}),e.jsxs("p",{children:["The directory runs on Supabase — Postgres for the company data plus the SSR auth helpers (",e.jsx("code",{children:"@supabase/ssr"}),") so server components can read data securely. Modeling the schema for flexible search was the core work: companies have services, locations, sizes, and specialties, and the UI needs to filter across all of them quickly. Postgres indexes and a clean query layer keep discovery fast even as the dataset grows."]}),e.jsx("h3",{children:"An Immersive 3D Landing"}),e.jsx("p",{children:"First impressions matter for a directory that wants to be the default. The landing page uses react-three-fiber over Three.js for an animated 3D hero that sets BPOAI apart from a generic listing site. The challenge is always the same: a heavy 3D scene must not wreck load time or Core Web Vitals, so the experience is scoped, lazy-loaded, and tuned to stay smooth on mid-range hardware."}),e.jsx("h3",{children:"Motion as a Product Feature"}),e.jsx("p",{children:"Framer Motion handles transitions throughout — page changes, card reveals, and micro-interactions. On a B2B product, polish reads as credibility. Buyers comparing outsourcing partners are making a high-trust decision, and a site that feels considered earns more of that trust than one that feels like a spreadsheet with a logo."}),e.jsx("h3",{children:"Lead Capture with Resend"}),e.jsx("p",{children:"Discovery is only half the job; the product has to convert interest into contact. Demo-request and contact flows are delivered by email via Resend, so an interested visitor becomes a real lead in the team's inbox without any third-party form middleware."}),e.jsx("h3",{children:"Deploying on Cloudflare via OpenNext"}),e.jsxs("p",{children:["BPOAI deploys to Cloudflare using ",e.jsx("code",{children:"@opennextjs/cloudflare"}),", which adapts a Next.js 16 app to Cloudflare's runtime. It's a great fit for a globally accessed directory — edge distribution keeps the site fast worldwide — but it does mean being deliberate about which Node APIs you reach for, since the runtime isn't a standard Node server."]}),e.jsx("h3",{children:"Takeaways"}),e.jsx("p",{children:`The lesson from BPOAI is that "directory" doesn't have to mean "boring." A solid Supabase schema makes the data trustworthy and searchable; a restrained 3D landing and Framer Motion make it memorable; and Resend turns browsing into pipeline. Combine those and a listing site becomes a product.`})]})},"ai-assisted-recruitment-platform-nextjs-mongodb":{title:"An AI-Assisted Recruitment Platform with Next.js and MongoDB",date:"May 24, 2026",dateISO:"2026-05-24",description:"How VoltOutreach streamlines hiring — job listings, candidate applications, an admin dashboard, and AI-assisted outreach with the Anthropic SDK, Cloudinary, and Calendly.",tags:["Next.js","MongoDB","Anthropic AI","Recruitment","Cloudinary"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Recruitment is a pipeline problem: jobs go up, candidates apply, someone reviews them, interviews get scheduled, and outreach never stops. VoltOutreach, which I led at AIDEVGEN, is an end-to-end portal that runs that whole pipeline — with AI assistance where the manual effort hurts most. Here's the architecture."}),e.jsx("h3",{children:"Public Portal vs Admin, Cleanly Separated"}),e.jsx("p",{children:"The app is built on Next.js 16 with React 19 and TypeScript, and the first design decision was a hard separation between the candidate-facing portal and the admin area using route groups. Candidates browse jobs and apply; admins manage listings, review applications, and handle leads behind middleware-protected routes. Keeping these concerns apart keeps both the code and the security model clean."}),e.jsx("h3",{children:"The Data Model (MongoDB + Mongoose)"}),e.jsx("p",{children:"MongoDB with Mongoose backs the platform, with models for jobs, supplemental job data, applications, and leads. Recruitment data is naturally document-shaped — an application bundles a candidate, a role, answers, and attachments — so a document store fits well. The schema is built for flexibility because every client wants slightly different fields on a job posting."}),e.jsx("h3",{children:"AI-Assisted Outreach"}),e.jsx("p",{children:"The standout feature is AI-assisted outreach via the Anthropic SDK. Drafting personalized messages to candidates and clients is the most repetitive, time-consuming part of recruiting, so the platform drafts it for you. The key is keeping the AI controllable — it accelerates the human rather than replacing the judgment, and admins always review before anything goes out."}),e.jsx("h3",{children:"Scheduling and Media"}),e.jsxs("p",{children:["Interview scheduling is handled with an embedded Calendly flow (",e.jsx("code",{children:"react-calendly"}),"), so booking happens without leaving the app. CV and document uploads go to Cloudinary, which offloads file storage and delivery from the application server and keeps media fast and reliable."]}),e.jsx("h3",{children:"Secure Sessions with jose"}),e.jsxs("p",{children:["Authentication uses JWT sessions implemented with ",e.jsx("code",{children:"jose"}),", paired with bcryptjs for password hashing. Sessions are validated in middleware, which is exactly where the public/admin route split is enforced — a request for an admin route without a valid session never reaches the page."]}),e.jsx("h3",{children:"Lessons"}),e.jsx("p",{children:"VoltOutreach reinforced two things. First, separating portal and admin behind route groups from day one avoids a tangle later. Second, AI is most valuable when aimed at a specific, painful, repeatable task — here, outreach drafting — rather than sprinkled everywhere. Consolidating jobs, applications, scheduling, and media into one dashboard is what turns a pile of tools into a platform."})]})},"barcode-scanning-water-quality-mobile-gemini":{title:"Barcode Scanning Meets Water Quality: PureX on Expo + Gemini",date:"May 12, 2026",dateISO:"2026-05-12",description:"Building PureX — a React Native app that scans product barcodes for nutrition and safety insights and surfaces location-based water-quality reports, powered by Google Gemini and Supabase.",tags:["React Native","Expo","Google Gemini","Supabase","Mobile Dev"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"PureX turns a phone into a personal health-and-safety scanner. Point the camera at a product barcode to get AI-analyzed nutrition and safety insights, or use your location to pull water-quality reports for your area. I built it at AIDEVGEN with React Native and Expo, Google Gemini for analysis, and Supabase on the back end. Here's how the pieces fit."}),e.jsx("h3",{children:"Camera and Location, the Native Way"}),e.jsxs("p",{children:["Barcode scanning runs on ",e.jsx("code",{children:"expo-camera"})," and water-quality lookups on ",e.jsx("code",{children:"expo-location"}),". Getting scanning to feel instant across a wide range of products and lighting conditions is the real work — the camera pipeline has to be responsive, give clear feedback, and degrade gracefully when a code is damaged or unusual. Expo's modules made this far less painful than wiring native code by hand."]}),e.jsx("h3",{children:"Turning Raw Data into Trustworthy Insights"}),e.jsxs("p",{children:["A barcode or a location reading is meaningless on its own. Google Gemini (",e.jsx("code",{children:"@google/genai"}),") interprets the scanned product or regional data into clear, actionable insights — what's in a product, what to watch for, what a water report actually means for you. The bar here is trust: the output has to be readable and reliable, because people are making health decisions on it."]}),e.jsx("h3",{children:"Supabase Backend"}),e.jsxs("p",{children:["Supabase handles data and authentication. Pairing it with Apple authentication (",e.jsx("code",{children:"expo-apple-authentication"}),") gives a fast, privacy-respecting sign-in that iOS users expect, while Supabase stores user data and history behind it."]}),e.jsx("h3",{children:"Subscriptions with RevenueCat"}),e.jsxs("p",{children:["The premium tier is powered by RevenueCat (",e.jsx("code",{children:"react-native-purchases"}),"), which abstracts the cross-platform pain of in-app purchases. Integrating subscriptions and Apple auth cleanly inside an Expo dev-client build takes care — build properties and entitlements have to line up — but RevenueCat removes most of the receipt-validation drudgery."]}),e.jsx("h3",{children:"Native Polish"}),e.jsxs("p",{children:["The details are what make a utility app feel premium: haptics, blur, gradients, push notifications, and the ability to generate and share reports with ",e.jsx("code",{children:"expo-print"})," and ",e.jsx("code",{children:"expo-sharing"}),'. Each is a small Expo module, but together they push the app from "functional" to "feels native."']}),e.jsx("h3",{children:"Takeaways"}),e.jsx("p",{children:"PureX is a reminder that a focused mobile app can combine camera, location, and AI into something genuinely useful without becoming bloated. Expo carried the heavy native lifting; the product work was making the AI insights trustworthy and the scanning fast. Get those two right and the rest is polish."})]})},"production-ready-auth-nextauth-v5-mongodb":{title:"Production-Ready Auth with NextAuth v5 and MongoDB",date:"May 02, 2026",dateISO:"2026-05-02",description:"A practical guide to the full account lifecycle — sign-up, login, protected routes, and email-based password reset — built with Next.js 16, NextAuth v5, MongoDB, and Nodemailer.",tags:["Next.js","NextAuth","MongoDB","Authentication","Security"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Authentication is the feature everyone needs and nobody enjoys rebuilding. I built Auth System at AIDEVGEN as a production-ready foundation that handles the whole account lifecycle — registration, login, protected routes, and email-based password reset — on Next.js 16 and NextAuth v5. Here's what goes into doing it properly."}),e.jsx("h3",{children:"NextAuth v5 with a Credentials Provider"}),e.jsx("p",{children:"The app uses NextAuth v5 (beta) with a credentials provider, which gives you full control over the login flow while still leaning on a battle-tested session layer. Passwords are hashed with bcryptjs before they ever touch the database — storing anything reversible is a non-starter — and the provider verifies the hash on sign-in."}),e.jsx("h3",{children:"Middleware-Protected Routes"}),e.jsx("p",{children:"Protected pages are guarded in middleware: a request without a valid session is redirected before the page renders. Doing this at the middleware layer (rather than per-page checks) keeps protection consistent and centralizes the rule in one place, which is exactly where you want your security logic."}),e.jsx("h3",{children:"The Password-Reset Flow"}),e.jsx("p",{children:"The trickiest part of any auth system is password reset. Auth System implements it over email with Nodemailer and Gmail SMTP: the user requests a reset, receives a time-limited token by email, and sets a new password. The token has to be single-use and expiring, the email has to be reliable, and the whole flow has to fail safely — never revealing whether an address is registered."}),e.jsx("h3",{children:"Validation with Zod, End to End"}),e.jsx("p",{children:"Every form and API route is validated with Zod, and the same schemas run on both client and server. Sharing schemas means the rules can't drift between where the user is told something is invalid and where it's actually enforced — the server is the source of truth, and the client just mirrors it for a better UX."}),e.jsx("h3",{children:"MongoDB for Users and Tokens"}),e.jsx("p",{children:"MongoDB stores users and reset tokens. It's a simple data model, but the details matter: tokens carry an expiry, are removed once used, and are never logged. Keeping the token lifecycle tight is what keeps the reset flow from becoming an attack vector."}),e.jsx("h3",{children:"Why Build a Reusable Foundation"}),e.jsx("p",{children:"The point of Auth System is reuse. Auth is the same across most products — only the branding changes — so getting a secure, modern implementation right once and dropping it into the next project saves real time and avoids re-introducing the same subtle bugs. Registration, login, protected access, and recovery, done correctly, become a starting point rather than a recurring tax."})]})},"ai-lead-capture-trades-businesses":{title:"Building an AI Lead-Capture Platform for Trades Businesses",date:"April 18, 2026",dateISO:"2026-04-18",description:"How I built Plumber's Mate AI — an automation platform that captures leads, books jobs, sends quotes, collects payments, and re-engages old customers with Next.js 16 and React 19.",tags:["Next.js","AI Automation","SaaS","Lead Generation","Framer Motion"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Trades businesses — plumbers, electricians, HVAC techs — lose jobs every day because they can't answer the phone. They're under a sink, on a roof, or driving to the next call. Plumber's Mate AI is a platform I built with the AIDEVGEN team to close that gap: an AI that captures every lead, books the job, sends the quote, collects payment, and asks for the Google review — all without the owner touching a keyboard."}),e.jsx("h3",{children:"The Problem: Missed Calls = Missed Revenue"}),e.jsx("p",{children:"For a one-van plumbing business, a missed call is often a lost customer. The average plumber misses 30–40% of inbound calls, and most callers don't leave a voicemail — they just dial the next result on Google. That's not a lead management problem; it's a survival problem. The goal of Plumber's Mate AI is to make sure every inbound signal — call, form, text — becomes a booked job."}),e.jsx("h3",{children:"Stack: Next.js 16, React 19, and Framer Motion"}),e.jsxs("p",{children:["The dashboard is built on Next.js 16 with React 19 and TypeScript. The Webpack build mode (",e.jsx("code",{children:"next build --webpack"}),") keeps CI stable while we evaluate Turbopack for production. Tailwind CSS 4 handles styling, and Framer Motion powers the onboarding flow, quote animations, and the marketing landing page. The minimalist dependency list is intentional — every runtime dep adds surface area for security and bundle bloat, and trades-SaaS users don't care about 50 UI libraries."]}),e.jsx("h3",{children:"The Lead Capture Pipeline"}),e.jsx("p",{children:"When a lead comes in — via the website form, a missed-call webhook, or a text — it lands in a unified lead queue. The AI qualifies the lead by asking for job type, postcode, urgency, and preferred time window. Valid leads are auto-scheduled into the owner's calendar using availability rules, and the customer gets an instant booking confirmation with a quote link. No human touches it unless the AI flags ambiguity (emergency keywords, unusual job types, out-of-area postcodes)."}),e.jsx("h3",{children:"Quotes, Payments, and the Review Loop"}),e.jsx("p",{children:'Once a job is marked complete, the platform auto-generates a line-item invoice from the quote, sends it via email and SMS, and opens a Stripe-backed payment link. 24 hours after payment clears, it fires a Google review request with a one-tap link. This "complete → invoice → paid → review" loop is what moves a plumber from "I do jobs" to "I have a business" — Google reviews compound into more leads, and the cycle self-reinforces.'}),e.jsx("h3",{children:"Re-Engaging Old Leads"}),e.jsx("p",{children:"The most underrated feature is re-engagement. Every plumber has a CRM graveyard — old quotes never accepted, customers who ghosted. Plumber's Mate AI runs a weekly re-engagement job: it scores cold leads based on job type, time since last contact, and seasonality (boiler services before winter, drainage after storms), then sends a personalised nudge. We've seen 8–12% of dead leads reactivate this way."}),e.jsx("h3",{children:"Dashboard Architecture"}),e.jsxs("p",{children:["The owner dashboard is route-grouped into ",e.jsx("code",{children:"(dashboard)"}),", ",e.jsx("code",{children:"(admin)"}),", and ",e.jsx("code",{children:"(auth)"}),` segments. Leads, quotes, payments, and reviews each get a dedicated view, but the home screen is a single feed: "what needs your attention today." We deliberately resisted building a kitchen-sink CRM — trades owners don't have time to learn software. If a feature needs a tutorial, it doesn't ship.`]}),e.jsx("h3",{children:"Lessons Learned"}),e.jsx("p",{children:"Three things surprised me. First, SMS matters more than email — plumbers live in their messages app. Second, the onboarding offer page (/offer) converts 3x better than a generic pricing page because it frames the product around a specific pain. Third, Framer Motion on the landing page measurably increased trial signups — polish signals trust, and trades owners are understandably skeptical of software salespeople."}),e.jsx("p",{children:"Plumber's Mate AI is proof that vertical AI SaaS doesn't need to be flashy — it just needs to eliminate one painful, repetitive task and do it reliably. For plumbers, that task is never missing a job again."})]})},"canvas-ai-image-studio-fabricjs":{title:"Canvas-Based AI Image Studios with Fabric.js and Next.js",date:"April 10, 2026",dateISO:"2026-04-10",description:"A technical walkthrough of building Clay Imaginary — a drag-and-drop AI image studio with Fabric.js compositing, html2canvas export, and AI-powered generation for creators.",tags:["Fabric.js","Next.js","AI Image Gen","Canvas API","html2canvas"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Creators today don't want another text-to-image tool. They want a studio — a workspace where they can generate, composite, edit, and export polished visuals without bouncing between Photoshop, Figma, and five AI tabs. Clay Imaginary is that studio, built with AIDEVGEN using Next.js 15, React 19, and Fabric.js. Here's how the canvas engine, drag-and-drop layers, and AI generation pipeline come together."}),e.jsx("h3",{children:"Why Fabric.js Over Raw Canvas"}),e.jsxs("p",{children:["Raw ",e.jsx("code",{children:"<canvas>"})," is great for drawing, terrible for editing. You'd have to rebuild selection, transformation, grouping, serialization, and undo from scratch. Fabric.js gives you all of that out of the box — objects are first-class, each with position, rotation, scale, and event handlers. For Clay Imaginary, that meant we could focus on the creative features (AI generation, templates, exports) instead of reinventing a scene graph."]}),e.jsx("h3",{children:"The Layer System"}),e.jsxs("p",{children:["Every element on the canvas — an AI-generated image, a text headline, a shape, an uploaded asset — is a Fabric object with a ",e.jsx("code",{children:"layerId"}),". A side panel renders the layer stack, and react-draggable lets users reorder layers with a drag. Reordering updates Fabric's internal z-index, the canvas re-renders, and the layer panel stays in sync via a shared state store. It feels like Figma; it's a few hundred lines of code."]}),e.jsx("h3",{children:"Wiring Up AI Image Generation"}),e.jsx("p",{children:"Generation is a server-side API route that proxies to the image model — keeping API keys off the client and letting us rate-limit, log, and swap providers without a client update. The user types a prompt, picks a style preset, and hits generate. The returned image URL is loaded into a Fabric image object and dropped onto the canvas at the last click position, ready to be moved, scaled, or composited with other layers."}),e.jsx("h3",{children:"Showcase Templates"}),e.jsx("p",{children:"Cold-start is the enemy of creative tools — a blank canvas intimidates users. Clay Imaginary ships with a showcase gallery of templates: product mockups, recipe cards, finance infographics, meme formats, quote cards, AI tech news layouts, gym posts. Each template is a pre-populated Fabric scene the user can remix. This is also how the product sells itself — the showcase page doubles as a landing page and a starting point."}),e.jsx("h3",{children:"Export with html2canvas"}),e.jsxs("p",{children:["Fabric has its own ",e.jsx("code",{children:"toDataURL"})," method, but we use html2canvas for the final export because the studio overlays HTML UI (annotations, watermarks for free users, branding frames) on top of the canvas. html2canvas captures the composed DOM + canvas region as a single PNG, which is what users actually want to post to Instagram or LinkedIn. Fabric handles editing; html2canvas handles shipping."]}),e.jsx("h3",{children:"Performance: Keep the Canvas Small"}),e.jsxs("p",{children:["The naive approach is to render at full 4K resolution while editing. Don't. We render at a lower working resolution (usually 1024×1024 or 1080×1350 for social ratios) and upscale on export. This keeps drag, rotate, and scale interactions at 60fps even on mid-range laptops. For really large compositions, we use Fabric's ",e.jsx("code",{children:"renderOnAddRemove: false"})," and batch updates manually."]}),e.jsx("h3",{children:"Auth and Persistence"}),e.jsxs("p",{children:["Google OAuth via ",e.jsx("code",{children:"@react-oauth/google"})," handles sign-in. Projects serialize as Fabric JSON (via ",e.jsx("code",{children:"canvas.toJSON()"}),") and live in a backend store keyed by user ID. Deserializing a project restores every layer with its exact state — positions, rotations, opacities, filters. This makes project sharing trivial: a URL + a JSON blob = a fully editable remix."]}),e.jsx("h3",{children:"What I'd Do Differently"}),e.jsx("p",{children:"If I were starting Clay Imaginary over, I'd invest earlier in a proper undo/redo history stack. Fabric's event model makes it possible but not free — you need to snapshot state on every mutation. Bolting it on later is painful. I'd also build the template system as a first-class primitive from day one rather than as a gallery layered on top."}),e.jsx("p",{children:"Canvas-based AI tools are a growing category, and Fabric.js + Next.js is a surprisingly capable stack. If you're building something like Clay Imaginary, skip the pure-canvas detour and stand on the shoulders of a mature scene graph — your users want features, not reinvented wheels."})]})},"nextjs-20-whats-new":{title:"Next.js 20: Everything New You Need to Know",date:"March 28, 2026",dateISO:"2026-03-28",description:"From React Server Functions to the revamped Turbopack pipeline and native Edge-first routing—here's what makes Next.js 20 the biggest release yet.",tags:["Next.js","React","Turbopack","Edge Computing","Full-Stack"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Next.js 20 just dropped, and it's not an incremental update—it's a rethinking of how modern full-stack React applications should be built. From a completely rewritten build pipeline to first-class edge primitives, here's everything that matters in this release."}),e.jsx("h3",{children:"Turbopack: Now the Default"}),e.jsx("p",{children:"Turbopack is no longer opt-in. Next.js 20 ships with Turbopack as the default bundler for both development and production builds. Cold starts are up to 10x faster than webpack, and incremental builds in large monorepos now complete in under 200ms. The migration is seamless—existing next.config.js options are fully compatible, and the webpack escape hatch is still available for edge cases."}),e.jsx("h3",{children:"React Server Functions"}),e.jsx("p",{children:"Server Actions have been replaced by React Server Functions—a more flexible primitive that works beyond form submissions. You can now call server-side logic from any client event handler, useEffect, or even other server components. Type safety is baked in with automatic TypeScript inference between client and server boundaries, eliminating the boilerplate of manual API routes for most use cases."}),e.jsx("h3",{children:"Edge-First Routing"}),e.jsx("p",{children:"Next.js 20 introduces a new routing layer designed for edge deployment. Routes can declare their runtime preference—Node.js, Edge, or Static—at the file level with a single export. The framework automatically optimizes data fetching and rendering strategy based on the declared runtime, giving you Cloudflare Workers-level latency with zero configuration."}),e.jsx("h3",{children:"Partial Prerendering (Stable)"}),e.jsx("p",{children:"PPR is now stable and enabled by default. It combines static shell rendering with streaming dynamic content, delivering instant page loads while still serving personalized data. The HTML shell is served from the CDN edge in under 50ms, and dynamic holes are filled via streaming as the server resolves them—no client-side loading spinners required."}),e.jsx("h3",{children:"Built-in Database Layer"}),e.jsx("p",{children:"The most surprising addition is next/db—a built-in database abstraction layer. It provides a lightweight ORM-like API that works with Postgres, SQLite, and Turso out of the box. Migrations are file-based and run automatically in development. For prototyping and small-to-medium apps, you no longer need Prisma or Drizzle as a dependency."}),e.jsx("h3",{children:"Dev Overlay 2.0"}),e.jsx("p",{children:"The development experience gets a major upgrade with the new Dev Overlay. It shows real-time rendering waterfall diagrams, component-level performance metrics, and a visual route inspector. You can see exactly which components are server-rendered vs. client-rendered, track hydration mismatches, and profile slow data fetches—all without leaving the browser."}),e.jsx("h3",{children:"Image and Font Optimization"}),e.jsx("p",{children:"next/image now supports automatic AVIF generation with smart format negotiation. The new next/font engine pre-computes font subsets at build time based on actual character usage in your app, reducing font payloads by up to 60%. Both features work seamlessly at the edge with no additional configuration."}),e.jsx("h3",{children:"Breaking Changes to Watch"}),e.jsx("p",{children:"The pages/ directory is officially deprecated—existing projects will still work, but new features target app/ exclusively. The minimum Node.js version is now 20 LTS. getServerSideProps and getStaticProps are removed in favor of Server Functions and the fetch cache API. If you're migrating from Next.js 19, the codemods handle most of the transition automatically."}),e.jsx("p",{children:"Next.js 20 is the most ambitious release since the App Router was introduced. Whether you're building a SaaS dashboard, an e-commerce platform, or a content-heavy site, this version gives you the tools to ship faster with less code. The future of full-stack React is here."})]})},"openclaw-deep-dive-setup":{title:"OpenClaw Deep Dive: Building Your Own AI Agent Pipeline",date:"March 22, 2026",dateISO:"2026-03-22",description:"A hands-on technical walkthrough of setting up OpenClaw from scratch—configuring channels, creating custom skills, wiring up tool chains, and deploying your personal AI agent stack.",tags:["OpenClaw","AI Agents","Tutorial","Self-Hosted","DevOps"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"In a previous post, I covered what OpenClaw is and why it matters. This time, we're going hands-on. I'll walk you through setting up OpenClaw from zero, connecting it to your messaging apps, building custom skills, and deploying a production-grade AI agent pipeline on your own hardware."}),e.jsx("h3",{children:"Prerequisites and Installation"}),e.jsx("p",{children:"You'll need Docker, Node.js 20+, and API keys for your preferred LLM provider (Claude, GPT, or a local model via Ollama). Start by cloning the OpenClaw repo and running the bootstrap script. The CLI wizard walks you through setting your gateway port, encryption passphrase, and default model. Within 3 minutes, you'll have a running Gateway process accessible at localhost."}),e.jsx("h3",{children:"Connecting Your First Channel: WhatsApp"}),e.jsx("p",{children:"OpenClaw uses the WhatsApp Business API through a lightweight bridge container. Run the channel setup command, scan the QR code with your phone, and the bridge establishes a persistent WebSocket connection. From this point, every message you send to your WhatsApp number is intercepted by the Gateway, processed through your configured AI model, and the response is delivered back—all in under 2 seconds."}),e.jsx("h3",{children:"Adding Telegram and Discord"}),e.jsx("p",{children:"Telegram integration requires a Bot Token from BotFather. Discord uses a bot application with message content intent enabled. Both channels are configured via a single YAML file—specify the token, target channels or groups, and permission rules. The Gateway multiplexes all channels through a unified message bus, so your AI maintains context whether you message from WhatsApp, Telegram, or Discord."}),e.jsx("h3",{children:"Building a Custom Skill: GitHub PR Reviewer"}),e.jsx("p",{children:`Skills are the heart of OpenClaw's extensibility. Let's build one that reviews GitHub pull requests on command. Create a new skill directory, define the skill manifest with trigger phrases and required parameters, then write the handler function. The handler receives the parsed user message, calls the GitHub API to fetch the PR diff, sends it to your LLM with a review prompt, and returns the formatted review. Register the skill, restart the Gateway, and now you can message "review PR #42 on my-repo" from any channel.`}),e.jsx("h3",{children:"Tool Chains and Multi-Step Workflows"}),e.jsx("p",{children:`Single skills are powerful, but tool chains unlock real automation. OpenClaw's pipeline system lets you compose skills sequentially—for example, a "deploy" command that first runs tests via your CI API, waits for results, creates a release tag, triggers a deployment webhook, and reports status back to your chat. Each step has access to the previous step's output, and the pipeline supports conditional branching and error handling.`}),e.jsx("h3",{children:"Memory and Context Management"}),e.jsx("p",{children:"OpenClaw stores conversation history in a local SQLite database with vector embeddings for semantic search. This means your AI remembers past conversations and can reference them naturally. You can configure memory retention periods, per-channel isolation (so work and personal contexts don't bleed), and manual memory injection for bootstrapping the AI with project-specific knowledge."}),e.jsx("h3",{children:"Running Multiple Agents"}),e.jsx("p",{children:"For complex setups, OpenClaw supports multi-agent routing. Define specialized agents—one for code tasks using Claude, another for creative writing using GPT, a third for local-only queries using Ollama. The router agent analyzes incoming messages and delegates to the appropriate specialist. Each agent maintains its own system prompt, tool access, and memory namespace while sharing the unified channel layer."}),e.jsx("h3",{children:"Production Deployment"}),e.jsx("p",{children:"For always-on operation, deploy OpenClaw with Docker Compose. The stack includes the Gateway, channel bridges, a Redis instance for rate limiting and queuing, and an optional Grafana dashboard for monitoring message throughput and latency. Use a reverse proxy like Caddy for TLS termination if you want to expose the Web Control UI externally. Set up systemd or Docker restart policies so the Gateway survives reboots."}),e.jsx("h3",{children:"Security Hardening"}),e.jsx("p",{children:"Before going live, lock down your deployment. Enable allowlist-only messaging so only approved contacts can interact with your AI. Set rate limits per channel to prevent abuse. Encrypt the SQLite database at rest. Store API keys in a secrets manager or encrypted .env file rather than plain text config. Audit the skill permissions—limit file system and network access to only what each skill needs."}),e.jsx("p",{children:"OpenClaw gives you the building blocks to create an AI assistant that's truly yours—tailored to your workflows, running on your terms, and extensible enough to grow with your needs. The 5-minute setup gets you started, but this deep dive shows that the ceiling is as high as your imagination."})]})},"react-native-expo-2026":{title:"React Native with Expo in 2026: The Ultimate Mobile Stack",date:"March 15, 2026",dateISO:"2026-03-15",description:"How Expo 54 and React Native 0.81 are making cross-platform mobile development faster than ever—from EAS builds to native modules.",tags:["React Native","Expo","Mobile Dev","TypeScript","Cross-Platform"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"React Native has come a long way, and with Expo 54 paired with React Native 0.81, 2026 is shaping up to be the best time ever to build cross-platform mobile apps. The developer experience is smoother, the ecosystem is mature, and the gap between native and cross-platform performance has virtually disappeared."}),e.jsx("h3",{children:"Why Expo in 2026?"}),e.jsx("p",{children:'Expo has evolved from a "quick prototyping tool" to a full production-grade platform. With EAS (Expo Application Services), you get cloud builds, OTA updates, and submission to app stores—all without touching Xcode or Android Studio. The new Expo Router brings file-based routing to mobile, mirroring the Next.js experience developers already love.'}),e.jsx("h3",{children:"React Native 0.81: What's New"}),e.jsx("p",{children:"The latest React Native release brings significant improvements to the New Architecture with Fabric renderer and TurboModules now stable by default. JSI (JavaScript Interface) enables direct communication between JavaScript and native code without the bridge, resulting in dramatically faster performance for heavy operations."}),e.jsx("h3",{children:"TypeScript-First Development"}),e.jsx("p",{children:"TypeScript is no longer optional in the React Native ecosystem—it's the standard. Expo 54 ships with full TypeScript support out of the box, and the type definitions for React Native APIs are comprehensive. Combined with Zustand for state management and typed navigation, you get end-to-end type safety across your entire mobile app."}),e.jsx("h3",{children:"Native Modules Made Easy"}),e.jsx("p",{children:"The days of ejecting from Expo to use native modules are over. Expo Modules API lets you write native Swift/Kotlin code that integrates seamlessly with your JavaScript layer. Config plugins handle native configuration automatically, so you can use libraries like react-native-google-signin, expo-camera, and expo-av without manual linking."}),e.jsx("h3",{children:"Real-World Performance"}),e.jsx("p",{children:"In our FreeNote app built with this stack, we achieved sub-100ms screen transitions, smooth 60fps animations with Reanimated, and audio recording with real-time duration tracking—all sharing 95% of code between iOS and Android. The performance is indistinguishable from fully native apps."}),e.jsx("h3",{children:"The Startup Stack"}),e.jsx("p",{children:"For startups, the React Native + Expo combination is unbeatable. One team, one codebase, two platforms, plus web support via Expo Web. Pair it with Firebase or Supabase for backend, RevenueCat for subscriptions, and you have a complete production stack that can go from idea to App Store in weeks, not months."}),e.jsx("p",{children:"If you're starting a mobile project in 2026, React Native with Expo isn't just a good choice—it's the obvious one."})]})},"openclaw-personal-ai-gateway":{title:"OpenClaw: Your Personal AI Gateway to Messaging Apps",date:"March 10, 2026",dateISO:"2026-03-10",description:"How OpenClaw bridges WhatsApp, Telegram, Discord, and iMessage with AI agents—giving you a self-hosted, privacy-first AI assistant.",tags:["OpenClaw","AI Agents","Self-Hosted","WhatsApp","Automation"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Imagine having a personal AI assistant that lives inside your WhatsApp, Telegram, Discord, and iMessage—one that runs on your own hardware, keeps your data private, and can actually do things like clear your inbox, manage your calendar, and browse the web. That's OpenClaw, and it's changing how developers interact with AI."}),e.jsx("h3",{children:"What Is OpenClaw?"}),e.jsx("p",{children:"OpenClaw is an open-source, self-hosted AI gateway that bridges your messaging apps with powerful AI agents. Unlike cloud-hosted AI assistants, OpenClaw runs entirely on your machine as a single Gateway process. Your conversations, data, and API keys never leave your hardware. It's MIT licensed and takes about 5 minutes to set up."}),e.jsx("h3",{children:"Multi-Channel Architecture"}),e.jsx("p",{children:"The killer feature is multi-channel connectivity. One Gateway process simultaneously manages WhatsApp, Telegram, Discord, Slack, Signal, and iMessage. You configure each channel once, and your AI assistant becomes available across all your messaging platforms with persistent memory and context across conversations."}),e.jsx("h3",{children:"Agent-Native Design"}),e.jsx("p",{children:"OpenClaw isn't just a chatbot wrapper—it's built for agentic AI. It supports tool use, sessions, memory, and multi-agent routing with isolated workspaces. Your AI can browse the web, write and execute code, interact with APIs, manage files, and control your system. It works with Claude, GPT, and local models, giving you flexibility in choosing your AI backbone."}),e.jsx("h3",{children:"Real-World Use Cases"}),e.jsx("p",{children:`The possibilities are practical and powerful. Send a WhatsApp message like "check me in for my flight tomorrow" and OpenClaw handles it. Ask it to "summarize my unread emails" via Telegram and get a concise digest. Tell it to "create a PR for the bug fix on branch hotfix-auth" through Discord and it executes the git commands. With 50+ integrations including Spotify, Gmail, GitHub, and Obsidian, it's a true digital assistant.`}),e.jsx("h3",{children:"Setting It Up"}),e.jsx("p",{children:"Installation is a one-liner: run the install script, then use the onboard wizard to configure authentication, gateway settings, and channels. The Web Control UI at localhost gives you a browser dashboard for chat management and session monitoring. For mobile access, iOS and Android companion apps are available with voice capabilities."}),e.jsx("h3",{children:"Privacy-First Philosophy"}),e.jsx("p",{children:"In an era where every AI service wants your data, OpenClaw takes the opposite approach. Everything runs locally—your conversations aren't training someone else's model. You bring your own API keys, choose your own models, and maintain full control. For developers handling sensitive code or business data, this is a game-changer."}),e.jsx("h3",{children:"The Extensibility Factor"}),e.jsx("p",{children:"OpenClaw's plugin system means the community can add new channels, tools, and capabilities. It can self-generate new skills based on your requests, and the growing ecosystem of community skills means functionality keeps expanding without core updates."}),e.jsx("p",{children:"OpenClaw represents the future of personal AI—not a cloud service you subscribe to, but an open-source tool you own and control. For developers who want AI that actually does things while respecting privacy, it's worth the 5-minute setup."})]})},"ai-automation-future":{title:"AI Automation: Transforming the Future of Work",date:"February 27, 2026",dateISO:"2026-02-27",description:"Explore how AI-driven automation is reshaping industries—from intelligent workflows and autonomous coding agents to no-code platforms.",tags:["AI","Automation","LLMs","Workflows","Future Tech"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Artificial intelligence is no longer just a buzzword—it's actively reshaping how we build software, run businesses, and think about productivity. From automated code reviews to entire workflows orchestrated by AI agents, automation powered by large language models is accelerating at an unprecedented pace."}),e.jsx("h3",{children:"1. What Is AI Automation?"}),e.jsx("p",{children:"AI automation refers to using intelligent systems to perform tasks that traditionally required human intervention. Unlike rule-based automation (if-this-then-that), AI automation can understand context, adapt to new inputs, and make decisions in ambiguous situations. This includes everything from auto-generating code and summarizing documents to managing CI/CD pipelines and triaging customer support tickets."}),e.jsx("h3",{children:"2. Intelligent Workflows with LLMs"}),e.jsx("p",{children:"Large language models like GPT-4 and Claude have unlocked a new class of automation. Developers are now building agentic workflows where an AI reads a task description, breaks it into subtasks, executes each one using tools (APIs, databases, file systems), and delivers a finished result. Frameworks like LangChain, CrewAI, and the Claude Agent SDK make it possible to chain LLM calls with real-world actions."}),e.jsx("h3",{children:"3. AI in Software Development"}),e.jsx("p",{children:"In the dev world, AI automation is already mainstream. Tools like GitHub Copilot, Cursor, and Claude Code assist with code generation, debugging, and refactoring. But the frontier is moving toward fully autonomous coding agents that can take a feature request, write the implementation, add tests, and open a pull request—all without human intervention."}),e.jsx("h3",{children:"4. No-Code and Low-Code AI Platforms"}),e.jsx("p",{children:"AI is also democratizing automation for non-developers. Platforms like Zapier AI, Make, and n8n now integrate LLM-powered steps into visual workflow builders. Business teams can automate report generation, data extraction, email drafting, and content scheduling without writing a single line of code."}),e.jsx("h3",{children:"5. Real-World Use Cases"}),e.jsx("p",{children:"Companies are deploying AI automation across every department. Marketing teams use AI to generate and A/B test ad copy at scale. Finance teams automate invoice processing and anomaly detection. DevOps teams leverage AI to predict infrastructure failures and auto-scale resources. Customer support teams deploy AI agents that resolve 60-70% of tickets without human escalation."}),e.jsx("h3",{children:"6. Challenges and Risks"}),e.jsx("p",{children:"AI automation is powerful but not without risks. Hallucinations can lead to incorrect outputs if not properly validated. Over-reliance on automation without human oversight can introduce subtle bugs or security vulnerabilities. There are also ethical concerns around job displacement and the need for responsible deployment. The key is treating AI as an augmentation tool—keeping humans in the loop for critical decisions."}),e.jsx("h3",{children:"7. The Developer's Evolving Role"}),e.jsx("p",{children:"As AI handles more routine tasks, developers are shifting from writing every line of code to becoming orchestrators—designing systems, reviewing AI-generated output, and focusing on architecture and user experience. The developers who thrive will be those who learn to leverage AI effectively, not compete against it."}),e.jsx("p",{children:"AI automation is not a distant future—it's happening now. Whether you're building AI-powered products or using AI tools to boost your own productivity, understanding and embracing this shift is essential for staying ahead in the rapidly evolving tech landscape."})]})},"web-performance-optimization":{title:"Web Performance Optimization: A Complete Guide",date:"January 20, 2026",dateISO:"2026-01-20",description:"Master code splitting, lazy loading, image optimization, caching strategies, and Core Web Vitals to build blazing-fast web applications.",tags:["Performance","Core Web Vitals","Caching","Lazy Loading","SEO"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Website speed directly impacts user experience, SEO rankings, and conversion rates. Studies show that a 1-second delay in page load time can result in a 7% reduction in conversions. Here's a comprehensive guide to making your web applications lightning-fast."}),e.jsx("h3",{children:"1. Code Splitting & Lazy Loading"}),e.jsx("p",{children:"Instead of loading your entire application upfront, split your code into smaller chunks that load on demand. In React, use dynamic imports with React.lazy() and Suspense to defer loading of components until they're needed. This dramatically reduces initial bundle size and Time to Interactive (TTI)."}),e.jsx("h3",{children:"2. Image Optimization"}),e.jsx("p",{children:"Images often account for 50%+ of page weight. Use modern formats like WebP or AVIF for 30-50% smaller file sizes. Implement responsive images with srcset to serve appropriately sized images based on device. Always specify width and height attributes to prevent layout shifts, and use lazy loading for below-the-fold images."}),e.jsx("h3",{children:"3. Caching Strategies"}),e.jsx("p",{children:"Implement a multi-layer caching approach: browser caching with proper Cache-Control headers, CDN caching for static assets, and service workers for offline-first experiences. Use cache busting with content hashes in filenames to ensure users get updated content while maximizing cache hits."}),e.jsx("h3",{children:"4. Critical Rendering Path Optimization"}),e.jsx("p",{children:'Inline critical CSS to eliminate render-blocking requests. Defer non-critical JavaScript with async or defer attributes. Preload essential resources like fonts and hero images using link rel="preload". Consider server-side rendering (SSR) or static site generation (SSG) for faster First Contentful Paint.'}),e.jsx("h3",{children:"5. Database & API Optimization"}),e.jsx("p",{children:"On the backend, optimize database queries with proper indexing and avoid N+1 query problems. Implement pagination for large datasets. Use GraphQL or sparse fieldsets to fetch only required data. Add Redis or Memcached for frequently accessed data to reduce database load."}),e.jsx("h3",{children:"6. Core Web Vitals"}),e.jsx("p",{children:"Focus on Google's Core Web Vitals: Largest Contentful Paint (LCP) should be under 2.5s, First Input Delay (FID) under 100ms, and Cumulative Layout Shift (CLS) under 0.1. Use tools like Lighthouse, WebPageTest, and Chrome DevTools to measure and monitor these metrics continuously."}),e.jsx("h3",{children:"7. Bundle Analysis & Tree Shaking"}),e.jsx("p",{children:"Regularly analyze your bundle with tools like webpack-bundle-analyzer. Remove unused dependencies and leverage tree shaking to eliminate dead code. Consider lighter alternatives for heavy libraries—for example, date-fns instead of moment.js can save 90% bundle size."}),e.jsx("h3",{children:"8. Network Optimization"}),e.jsx("p",{children:"Enable HTTP/2 or HTTP/3 for multiplexed connections. Use Brotli compression for 15-20% better compression than gzip. Minimize DNS lookups by reducing third-party scripts. Implement resource hints like dns-prefetch and preconnect for external domains."}),e.jsx("p",{children:"Performance optimization is an ongoing process, not a one-time task. Establish performance budgets, set up monitoring with tools like SpeedCurve or Calibre, and make performance a core part of your development workflow. Your users—and your business metrics—will thank you."})]})},"ai-powered-car-maintenance":{title:"Building an AI-Powered Car Maintenance App",date:"January 05, 2026",dateISO:"2026-01-05",description:"How I integrated Google Gemini AI with React Native to create intelligent dashboard light scanning, tire inspection, and maintenance quote analysis.",tags:["React Native","Google Gemini","AI/ML","Mobile Dev","Node.js"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Car maintenance can be confusing, especially when mysterious dashboard lights appear. I built an AI-powered mobile app using React Native and Google Gemini AI to help users understand and address their vehicle maintenance needs."}),e.jsx("h3",{children:"The Problem"}),e.jsx("p",{children:"Most car owners don't know what their dashboard warning lights mean, often ignoring critical issues or overpaying for simple fixes. Traditional solutions require manual lookups or expensive diagnostic tools."}),e.jsx("h3",{children:"Integrating Google Gemini AI"}),e.jsx("p",{children:"I chose Google Gemini for its powerful multimodal capabilities. The app uses the Gemini Vision API to analyze photos of dashboard lights and provide instant, accurate explanations of what each light means and recommended actions."}),e.jsx("h3",{children:"Dashboard Light Scanner"}),e.jsx("p",{children:"Users simply snap a photo of their dashboard. The AI identifies all visible warning lights, explains their meaning, urgency level, and provides step-by-step guidance on what to do next—whether it's a simple fix or requires professional attention."}),e.jsx("h3",{children:"Tire Inspection Feature"}),e.jsx("p",{children:"Beyond dashboard lights, the app can analyze tire conditions from photos. It detects wear patterns, tread depth issues, and potential alignment problems, helping users know when it's time for rotation or replacement."}),e.jsx("h3",{children:"Maintenance Quote Analysis"}),e.jsx("p",{children:"One of the most valuable features is the quote analyzer. Users can upload repair quotes from mechanics, and the AI evaluates whether the pricing is fair, identifies unnecessary services, and suggests questions to ask the mechanic."}),e.jsx("h3",{children:"Technical Implementation"}),e.jsx("p",{children:"The React Native app uses Expo for cross-platform deployment, with a Node.js backend handling Gemini API calls. I implemented image compression to optimize API costs and response times while maintaining accuracy."}),e.jsx("p",{children:"This project demonstrates how AI can democratize expertise, giving everyday car owners the knowledge they need to make informed maintenance decisions."})]})},"building-marketplace-with-escrow":{title:"Building a Secure Marketplace with Escrow Payments",dateISO:"2026-01-03",description:"A deep dive into implementing Stripe escrow payments, trade systems, and secure transactions for the Bible Trader marketplace.",tags:["Stripe","Payments","Security","E-commerce","React"],date:"January 03, 2026",content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Building a peer-to-peer marketplace requires solving one fundamental problem: trust. For Bible Trader, a platform where users buy, sell, and trade religious books and collectibles, I implemented a robust escrow payment system using Stripe."}),e.jsx("h3",{children:"Why Escrow Matters"}),e.jsx("p",{children:"In traditional marketplace transactions, either the buyer or seller takes on risk. Escrow eliminates this by holding funds until both parties confirm the transaction is complete, protecting everyone involved."}),e.jsx("h3",{children:"Stripe Connect Implementation"}),e.jsx("p",{children:'I used Stripe Connect with the "destination charges" model. When a buyer purchases an item, funds are captured but held in a pending state. The seller only receives payment once the buyer confirms delivery and satisfaction.'}),e.jsx("h3",{children:"The Trade System"}),e.jsx("p",{children:"Bible Trader allows direct trades between users—swapping items without money changing hands. I built a matching system where users can propose trades, and both parties must accept before items are marked for exchange."}),e.jsx("h3",{children:"Dispute Resolution Flow"}),e.jsx("p",{children:"Despite best efforts, disputes happen. I implemented a structured dispute process: either party can open a dispute within 48 hours of delivery, providing evidence through the app. Admins review cases and can release funds, issue refunds, or split the difference."}),e.jsx("h3",{children:"Security Considerations"}),e.jsx("p",{children:"Security was paramount. All sensitive operations use webhook verification to prevent spoofing. Payment intents are idempotent to prevent double-charges. User verification requires email confirmation and optional phone verification for high-value transactions."}),e.jsx("h3",{children:"Handling Edge Cases"}),e.jsx("p",{children:"Real-world scenarios required careful handling: what if a seller never ships? What if a buyer claims non-delivery falsely? I implemented automatic release timers, shipping integration for tracking verification, and a reputation system that influences dispute outcomes."}),e.jsx("p",{children:"Building this marketplace taught me that the technical payment integration is just the beginning—the real challenge is designing systems that handle human behavior at scale."})]})},"next-19-new-features":{dateISO:"2025-12-12",description:"Explore the groundbreaking features introduced in Next.js 19, from enhanced performance to new routing capabilities.",tags:["Next.js","React","TurboPack","Server Actions","Full-Stack"],title:"Next 19 New Features",date:"December 12, 2025",content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Next.js 19 has arrived, bringing a suite of powerful new features designed to streamline development and boost application performance."}),e.jsx("h3",{children:"1. Enhanced TurboPack"}),e.jsx("p",{children:"The build system has been completely overhauled with the latest version of TurboPack, offering up to 50% faster build times."}),e.jsx("h3",{children:"2. Server Actions 2.0"}),e.jsx("p",{children:"Server Actions have been refined for better type safety and easier error handling, making full-stack React even more seamless."}),e.jsx("h3",{children:"3. Built-in AI SDK Integration"}),e.jsx("p",{children:"Next.js 19 introduces native support for AI SDKs, simplifying the integration of LLMs into your applications."}),e.jsx("p",{children:"These features mark a significant step forward for the React framework, solidifying its position as a top choice for modern web development."})]})},"security-flaw-react2shell":{dateISO:"2025-12-10",description:"A critical look at the recently discovered security vulnerability in the react2shell library and how to mitigate it.",tags:["Security","Vulnerability","React","Code Audit","Best Practices"],title:"Security Flaw: react2shell",date:"December 10, 2025",content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"A critical security vulnerability has been identified in the popular `react2shell` library."}),e.jsx("h3",{children:"The Vulnerability"}),e.jsx("p",{children:"The flaw allows for potential arbitrary code execution if user input is not properly sanitized before being passed to the shell execution context."}),e.jsx("h3",{children:"Impact"}),e.jsx("p",{children:"Applications using `react2shell` versions prior to 1.4.5 are at risk. Attackers could exploit this to gain unauthorized access to the server environment."}),e.jsx("h3",{children:"Mitigation"}),e.jsx("p",{children:"Developers are urged to upgrade to version 1.4.5 or later immediately. If an upgrade is not possible, ensure strict input validation is in place for any data passed to the library."})]})},"ai-agents-revolution":{title:"The Rise of AI Agents",date:"December 08, 2025",dateISO:"2025-12-08",description:"How autonomous AI agents are transforming software development, automation, and the future of work.",tags:["AI Agents","Automation","LLMs","Future Tech","DevTools"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"We are witnessing a paradigm shift from passive AI tools to active AI agents capable of autonomous decision-making and task execution."}),e.jsx("h3",{children:"What are AI Agents?"}),e.jsx("p",{children:"Unlike traditional chatbots that wait for prompts, AI agents can perceive their environment, reason about goals, and take actions to achieve them. They can browse the web, write code, and interact with APIs independently."}),e.jsx("h3",{children:"Impact on Development"}),e.jsx("p",{children:'In software engineering, agents are evolving from simple code completion tools to "pair programmers" that can refactor entire codebases, write tests, and even deploy applications.'}),e.jsx("h3",{children:"The Future"}),e.jsx("p",{children:'As these agents become more reliable, we will see a shift towards "agentic workflows" where humans orchestrate teams of specialized AI agents to solve complex problems faster than ever before.'})]})},"code-speed-optimization":{dateISO:"2025-12-05",description:"Essential techniques to slash latency, optimize algorithms, and boost your application's response speed.",tags:["Algorithms","React","Performance","Optimization","Best Practices"],title:"Mastering Code & Speed Optimization",date:"December 05, 2025",content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"In today's fast-paced digital world, milliseconds matter. Optimizing your code for speed and efficiency is no longer optional—it's a necessity."}),e.jsx("h3",{children:"1. Algorithmic Efficiency"}),e.jsx("p",{children:"The foundation of optimization lies in choosing the right algorithms. Moving from O(n²) to O(n log n) can drastically reduce processing time for large datasets."}),e.jsx("h3",{children:"2. Minimizing Re-renders in React"}),e.jsx("p",{children:"For frontend performance, preventing unnecessary re-renders is key. Utilize `React.memo`, `useMemo`, and `useCallback` to ensure components only update when absolutely necessary."}),e.jsx("h3",{children:"3. Network Optimization"}),e.jsx("p",{children:"Reduce payload sizes by compressing assets, using code splitting, and implementing lazy loading. Efficient caching strategies can also significantly improve perceived response speeds."}),e.jsx("p",{children:"By focusing on these core areas, you can ensure your applications remain snappy and responsive, providing the best possible user experience."})]})}},f=()=>{const{id:s}=l(),t=h[s],i=n.useRef(null);return n.useEffect(()=>{if(!t)return;const o=a.context(()=>{a.timeline({defaults:{ease:"power3.out"}}).fromTo(".blog--back-link",{opacity:0,x:-30},{opacity:1,x:0,duration:.6}).fromTo(".blog-post .section--title",{opacity:0,y:30},{opacity:1,y:0,duration:.8},"-=0.3").fromTo(".blog-post .section--subtitle",{opacity:0,y:20},{opacity:1,y:0,duration:.5},"-=0.4").fromTo(".blog--content",{opacity:0,y:40},{opacity:1,y:0,duration:.8},"-=0.3"),a.fromTo(".blog--content p, .blog--content h3",{opacity:0,y:20},{opacity:1,y:0,duration:.5,stagger:.1,delay:.5})},i);return()=>o.revert()},[t]),t?e.jsxs("section",{className:"blog-post section",id:"blog-post",ref:i,children:[e.jsx(d,{title:`${t.title} | Wasif Rehman`,description:t.description||t.title,path:`/blog/${s}`,type:"article",article:{title:t.title,excerpt:t.description,datePublished:t.dateISO,tags:t.tags}}),e.jsxs("div",{className:"container",children:[e.jsxs(r,{to:"/blog",className:"blog--back-link",children:[e.jsx("i",{className:"ri-arrow-left-line"})," Back to Blogs"]}),e.jsx("h1",{className:"section--title",children:t.title}),e.jsx("span",{className:"section--subtitle",children:t.date}),e.jsx("div",{className:"blog--content",children:t.content})]})]}):e.jsxs("div",{className:"blog-post section container",children:[e.jsx("h2",{children:"Post not found"}),e.jsx(r,{to:"/blog",className:"button button--flex",children:"Back to Blog"})]})};export{f as default};
